mapper.select:
SELECT CR.*, O.OrderName, O.OrderState, CI.LoginId
FROM shopion.tOrdOrderCashRecipt CR
INNER JOIN shopion.tOrdOrder O ON CR.OrderNo = O.OrderNo
LEFT OUTER JOIN shopion.tPrfCust CI ON O.CustId = CI.CustId

    AND CR.OrderNo = #{pOrderNo}
    AND O.CustId = #{pCustId}

        AND (CR.ReciptDate >= DATE_FORMAT(#{pStartDate}, '%Y%m%d') AND CR.ReciptDate < ADDDATE(DATE_FORMAT(#{pEndDate}, '%Y%m%d'), INTERVAL 1 DAY))



    ORDER BY CR.${sidx} ${sord}
    ORDER BY CR.OrderNo DESC

mapper.update:
UPDATE shopion.tOrdOrderCashRecipt SET
    ReciptType = #{reciptType}, ReciptNo = #{reciptNo}, ReciptDate = #{reciptDate}, ReciptAmt = #{reciptAmt},
    CustName = #{custName}, CustEmail = #{custEmail}, PgResultCode = #{pgResultCode}, PgResultMsg = #{pgResultMsg},
    ChangeDate = NOW(), ChangeId = #{changeId}, ChangeName = #{changeName}
WHERE OrderNo = #{orderNo}
